exec python3 -c 'exec("import itertools,sys\n# ATGC is a reversible encoding of bit pairs; TM syntax is generated structurally.\nB={'"'"'A'"'"':(0,0),'"'"'T'"'"':(0,1),'"'"'G'"'"':(1,0),'"'"'C'"'"':(1,1)}\nE=lambda x,y:'"'"''"'"'.join('"'"'ATGC'"'"'[int(a+b,2)] for a,b in zip(x,y))\ndef machines(n):\n # n states 0..n-1; -1=HALT. Binary tape. Each (q,a) may be undefined or (q'"'"',b,L/R).\n acts=[None]+[(r,b,d) for r in range(-1,n) for b in (0,1) for d in (-1,1)]\n keys=[(q,a) for q in range(n) for a in (0,1)]\n for z in itertools.product(acts,repeat=len(keys)):\n  yield dict(zip(keys,z))\ndef step(M,c):\n q,h,t=c\n if q<0:return c\n a=t.get(h,0); z=M.get((q,a))\n if z is None:return None\n r,b,d=z;u=dict(t)\n if b:u[h]=1\n else:u.pop(h,None)\n return (r,h+d,u)\ndef bits(c):\n q,h,t=c\n # finite canonical snapshot sufficient for equality/trace display, not used to decide nonhalting\n lo=min([h,*t.keys()],default=h);hi=max([h,*t.keys()],default=h)\n return '"'"''"'"'.join(str(t.get(i,0)) for i in range(lo,hi+1))\ndef run(M,k):\n c=(0,0,{})\n for i in range(k):\n  z=step(M,c)\n  if z is None:return '"'"'CLOSED'"'"',i,'"'"''"'"'\n  if z==c:return '"'"'FIX'"'"',i,E(bits(c),bits(z))\n  c=z\n return '"'"'OPEN'"'"',k,'"'"''"'"'\n# Fair diagonal schedule: round r visits state-count n<=r and first r machines of each size for r steps.\nlimit=int(sys.argv[1]) if len(sys.argv)>1 else 0\nr=1\nwhile not limit or r<=limit:\n out={'"'"'FIX'"'"':0,'"'"'CLOSED'"'"':0,'"'"'OPEN'"'"':0};sample=None\n for n in range(1,r+1):\n  for j,M in zip(range(r),machines(n)):\n   s,k,w=run(M,r);out[s]+=1\n   if s=='"'"'FIX'"'"' and sample is None:sample=(n,j,k,w)\n print('"'"'ROUND'"'"',r,'"'"' '"'"'.join(f'"'"'{k}={v}'"'"' for k,v in out.items()),'"'"'SAMPLE_FIX='"'"'+repr(sample))\n r+=1")' "$@"
